Context {RESV : list (Z * Z)} {ATOP : Z}.
(* [comment removed for export] *)
Context {SBc PAc : Z}.
Local Notation INV := (AsanInv.INV RESV ATOP).
Local Notation AMI := (AsanInv.AMI RESV ATOP).
Local Notation AINV := (AsanInv.AINV ATOP).
